UPDATE tb_daily_cost
SET order_dist   = #{orderDist}
   ,lot_no        = #{lotNo}
   ,customer_name = #{customerName}
   ,item_name     = #{itemName}
   ,prod_type     = #{prodType}
   ,prod_qty      = #{prodQty}
   ,work_time     = #{workTime}
   ,man_f_cnt     = #{manFCnt}
   ,man_d_cnt     = #{manDCnt}
   ,wom_f_cnt     = #{womFCnt}
   ,wom_d_cnt     = #{womDCnt}
   ,man_f_cost    = #{manFCost}
   ,man_d_cost    = #{manDCost}
   ,wom_f_cost    = #{womFCost}
   ,wom_d_cost    = #{womDCost}
   ,etc           = #{etc}
   ,upd_id        = #{userId}
   ,upd_dt        = GETDATE()
WHERE daily_cost_id = #{dailyCostId}
